// Run first. The caller keeps these rows as they are: people who know at least one person, most connected first. `handle` keeps same-named people from being merged into one group.
query people_with_friends() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle
        $p.name
        count($f) as degree
    }
    order { degree desc }
}
```

```gq
// Run second. The caller appends these rows after the first result, giving each a `degree` of 0, because a traversal match cannot return people with no edges.
query people_without_friends() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}
